SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, ROW_NUMBER() OVER (ORDER BY A.FRST_REGIST_PNTTM DESC) AS RNUM, A.ROLE_ID, A.ROLE_NAME, A.ROLE_DC, TO_CHAR(A.FRST_REGIST_PNTTM, 'YYYY-MM-DD') AS ROLE_CREAT_DE, A.ROLE_USEYN, COALESCE(B.chk_menu, 0) AS chk_menu FROM TB_ROLEINFO A LEFT JOIN ( -- 메뉴 개수를 미리 계산하여 JOIN (성능 최적화) SELECT ROLE_ID, COUNT(*) AS chk_menu FROM COMTNMENUCREATDTLS GROUP BY ROLE_ID ) B ON A.ROLE_ID = B.ROLE_ID WHERE 1=1
AND ( A.ROLE_ID LIKE CONCAT('%', #{params.searchKeyword}, '%') OR A.ROLE_NAME LIKE CONCAT('%', #{params.searchKeyword}, '%') )
ORDER BY A.FRST_REGIST_PNTTM DESC LIMIT #{params.recordCountPerPage} OFFSET #{params.firstIndex}


SELECT COUNT(ROLE_ID) AS totcnt
FROM COMTNMENUCREATDTLS
WHERE ROLE_ID = #{roleId}
